() => {
  const inputs = document.querySelectorAll('input');
  const setVal = (el, v) => {
    const proto = Object.getPrototypeOf(el);
    const desc = Object.getOwnPropertyDescriptor(proto, 'value');
    desc.set.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
  };
  setVal(inputs[0], 'admin');
  setVal(inputs[1], 'admin123');
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('登'));
  return { inputs: inputs.length, btnDisabled: btn ? btn.disabled : null, btnText: btn ? btn.textContent : null };
}

