() => {
  // Find the modal: look for heading 使用指南
  const h2 = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.trim() === '使用指南');
  if (!h2) return 'modal not found';
  let panel = h2;
  // climb to the outermost fixed/absolute container
  while (panel.parentElement && panel.parentElement !== document.body) {
    const cs = getComputedStyle(panel.parentElement);
    panel = panel.parentElement;
    if (cs.position === 'fixed' && panel.parentElement === document.body) break;
  }
  // find scrollable element inside
  const all = [panel, ...panel.querySelectorAll('*')];
  const scrollables = all.filter(e => e.scrollHeight > e.clientHeight + 10 && /(auto|scroll)/.test(getComputedStyle(e).overflowY));
  const r = panel.getBoundingClientRect();
  return {
    panelClass: panel.className.slice(0, 120),
    panelRect: { w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top), left: Math.round(r.left) },
    panelPos: getComputedStyle(panel).position,
    scrollables: scrollables.map(s => ({
      cls: s.className.slice(0, 80),
      sh: s.scrollHeight, ch: s.clientHeight, st: s.scrollTop
    }))
  };
}

async () => {
  try {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="80"><foreignObject width="100%" height="100%"><div xmlns="http://www.w3.org/1999/xhtml" style="width:200px;height:80px;background:oklch(0.6 0.2 250);color:white;font-size:20px;display:flex;align-items:center;justify-content:center;">测试 Test</div></foreignObject></svg>`;
    const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    const img = new Image();
    await new Promise((res, rej) => { img.onload = res; img.onerror = () => rej(new Error('img load failed')); img.src = url; });
    const canvas = document.createElement('canvas');
    canvas.width = 200; canvas.height = 80;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(img, 0, 0);
    const dataUrl = canvas.toDataURL('image/png');
    return { ok: true, len: dataUrl.length, imgW: img.width, imgH: img.height };
  } catch (e) {
    return { ok: false, err: String(e) };
  }
}

() => {
  const h2 = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.trim() === '使用指南');
  if (!h2) return { err: 'modal not open' };
  // find overlay: climb until position fixed
  let el = h2;
  const chain = [];
  while (el && el !== document.body) {
    chain.push({ tag: el.tagName, cls: (el.className || '').toString().slice(0, 140) });
    el = el.parentElement;
  }
  // find the fixed overlay
  let overlay = h2;
  while (overlay.parentElement && overlay.parentElement !== document.body) {
    overlay = overlay.parentElement;
    if (getComputedStyle(overlay).position === 'fixed') break;
  }
  const styles = [];
  let cssError = null;
  try {
    for (const sheet of document.styleSheets) {
      try {
        let t = '';
        for (const rule of sheet.cssRules) t += rule.cssText + '\n';
        styles.push({ href: sheet.href, len: t.length });
      } catch (e) { styles.push({ href: sheet.href, err: String(e) }); }
    }
  } catch (e) { cssError = String(e); }
  return {
    overlayCls: (overlay.className || '').toString().slice(0, 200),
    overlayIsFixed: getComputedStyle(overlay).position,
    chain: chain.slice(0, 8),
    sheets: styles,
    cssError
  };
}

async () => {
  const log = [];
  try {
    const W = 1280, H = 800;
    // 1. locate modal
    const h2 = Array.from(document.querySelectorAll('h2')).find(h => h.textContent.trim() === '使用指南');
    if (!h2) return { err: 'modal not open' };
    let overlay = h2;
    while (overlay.parentElement && overlay.parentElement !== document.body) {
      overlay = overlay.parentElement;
      if (getComputedStyle(overlay).position === 'fixed') break;
    }
    const panel = overlay.querySelector('[class*="max-w-3xl"]') || overlay.firstElementChild;
    const scrollable = overlay.querySelector('[class*="overflow-y-auto"]');
    if (!panel || !scrollable) return { err: 'panel/scrollable not found' };
    log.push('modal found');

    // 2. collect CSS
    let css = '';
    for (const sheet of document.styleSheets) {
      try { for (const r of sheet.cssRules) css += r.cssText + '\n'; } catch (e) {}
    }
    log.push('css len=' + css.length);

    // 3. measure natural content height via off-screen stage (panel width fixed 768px)
    const stage = document.createElement('div');
    stage.style.cssText = 'position:fixed;left:-20000px;top:0;width:768px;visibility:hidden;pointer-events:none;';
    const panelClone = panel.cloneNode(true);
    panelClone.style.cssText += ';max-height:none;height:auto;max-width:768px;width:768px;';
    stage.appendChild(panelClone);
    document.body.appendChild(stage);
    const stageScroll = panelClone.querySelector('[class*="overflow-y-auto"]');
    stageScroll.style.cssText += ';overflow:visible;height:auto;flex:none;';
    const headerEl = panelClone.querySelector('[class*="border-b"]');
    const footerEl = panelClone.querySelector('[class*="border-t"]');
    const headerH = headerEl ? headerEl.getBoundingClientRect().height : 0;
    const footerH = footerEl ? footerEl.getBoundingClientRect().height : 0;
    const naturalH = stageScroll.scrollHeight;
    const panelMaxH = Math.round(H * 0.85); // max-h-[85vh]
    const scrollViewport = panelMaxH - headerH - footerH;
    const midScroll = Math.max(0, Math.round((naturalH - scrollViewport) / 2));
    // which headings visible at middle
    const heads = Array.from(stageScroll.querySelectorAll('h1,h2,h3')).map(h => {
      let y = 0, n = h;
      while (n && n !== stageScroll) { y += n.offsetTop; n = n.offsetParent; }
      return { t: h.textContent.trim().slice(0, 30), y };
    });
    const visibleMid = heads.filter(h => h.y >= midScroll - 20 && h.y <= midScroll + scrollViewport).map(h => h.t);
    document.body.removeChild(stage);
    log.push(`naturalH=${naturalH} headerH=${headerH} footerH=${footerH} scrollViewport=${scrollViewport} midScroll=${midScroll}`);

    // 4. capture function
    async function capture(shiftPx) {
      const clone = overlay.cloneNode(true);
      const sc = clone.querySelector('[class*="overflow-y-auto"]');
      if (shiftPx > 0) {
        sc.style.cssText += ';overflow:hidden;';
        let target = sc.firstElementChild;
        if (!target) {
          const wrap = document.createElement('div');
          while (sc.firstChild) wrap.appendChild(sc.firstChild);
          sc.appendChild(wrap);
          target = wrap;
        }
        target.style.marginTop = `-${shiftPx}px`;
      }
      const wrapper = document.createElement('div');
      wrapper.setAttribute('xmlns', 'http://www.w3.org/1999/xhtml');
      const style = document.createElement('style');
      style.textContent = css;
      wrapper.appendChild(style);
      wrapper.appendChild(clone);
      const xhtml = new XMLSerializer().serializeToString(wrapper);
      const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}"><foreignObject width="100%" height="100%">${xhtml}</foreignObject></svg>`;
      const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
      const img = new Image();
      await new Promise((res, rej) => { img.onload = res; img.onerror = () => rej(new Error('svg img load failed')); img.src = url; });
      const canvas = document.createElement('canvas');
      canvas.width = W; canvas.height = H;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0);
      // sanity: sample pixels to ensure not blank
      const d = ctx.getImageData(0, 0, W, H).data;
      let sum = 0;
      for (let i = 0; i < d.length; i += 4000) sum += d[i] + d[i+1] + d[i+2] + d[i+3];
      return { dataUrl: canvas.toDataURL('image/png'), pixelSum: sum };
    }

    function download(dataUrl, name) {
      const a = document.createElement('a');
      a.href = dataUrl;
      a.download = name;
      document.body.appendChild(a);
      a.click();
      a.remove();
    }

    const shot1 = await capture(0);
    log.push('shot1 bytes=' + shot1.dataUrl.length + ' pixelSum=' + shot1.pixelSum);
    download(shot1.dataUrl, 'help-guide-modal-top.png');
    await new Promise(r => setTimeout(r, 600));
    const shot2 = await capture(midScroll);
    log.push('shot2 bytes=' + shot2.dataUrl.length + ' pixelSum=' + shot2.pixelSum);
    download(shot2.dataUrl, 'help-guide-modal-mid.png');

    return { ok: true, log, visibleMid };
  } catch (e) {
    return { ok: false, err: String(e), log };
  }
}

